import json
import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _to_float(value: Any) -> Optional[float]:
    if value is None:
        return None
    try:
        if isinstance(value, dict):
            for key in ("content", "text", "value", "amount"):
                if key in value and value[key] is not None:
                    return _to_float(value[key])
            return None
        if hasattr(value, "value"):
            return _to_float(getattr(value, "value"))
        return float(str(value).replace(",", "").strip())
    except Exception:
        return None


def _field_content(field: Any) -> Optional[str]:
    if field is None:
        return None
    if isinstance(field, dict):
        for key in ("content", "text", "value", "name"):
            if key in field and field[key] is not None:
                return str(field[key]).strip()
        return None
    for attr in ("content", "text", "value"):
        if hasattr(field, attr):
            v = getattr(field, attr)
            if v is not None:
                return str(v).strip()
    return str(field).strip()


def _extract_items(items_field: Any) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    if not items_field:
        return items

    for item in items_field:
        item_dict: Dict[str, Any] = {}
        fields = getattr(item, "value", None) if hasattr(item, "value") else item
        if isinstance(fields, dict):
            item_fields = fields
        else:
            item_fields = {}
            for name in ("Description", "Quantity", "UnitPrice", "Amount", "ProductCode", "Tax", "Name"):
                if hasattr(fields, "get"):
                    pass

        if hasattr(item, "value") and isinstance(item.value, dict):
            item_fields = item.value
        elif isinstance(item, dict):
            item_fields = item

        if isinstance(item_fields, dict):
            desc = item_fields.get("Description") or item_fields.get("description") or item_fields.get("Name")
            qty = item_fields.get("Quantity") or item_fields.get("quantity")
            unit_price = item_fields.get("UnitPrice") or item_fields.get("unitPrice") or item_fields.get("unit_price")
            amount = item_fields.get("Amount") or item_fields.get("amount")
            tax = item_fields.get("Tax") or item_fields.get("tax")

            item_dict = {
                "description": _field_content(desc),
                "quantity": _to_float(qty),
                "unit_price": _to_float(unit_price),
                "amount": _to_float(amount),
                "tax": _to_float(tax),
            }
        else:
            desc = getattr(item_fields, "description", None)
            qty = getattr(item_fields, "quantity", None)
            unit_price = getattr(item_fields, "unit_price", None)
            amount = getattr(item_fields, "amount", None)
            tax = getattr(item_fields, "tax", None)
            item_dict = {
                "description": _field_content(desc),
                "quantity": _to_float(qty),
                "unit_price": _to_float(unit_price),
                "amount": _to_float(amount),
                "tax": _to_float(tax),
            }

        items.append({k: v for k, v in item_dict.items() if v is not None})
    return items


def extract_receipt_data(file_path: str) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(file_path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id="prebuilt-invoice",
            body=f,
            content_type="application/pdf",
        )
    result = poller.result()

    doc = result.documents[0] if getattr(result, "documents", None) else None
    fields = getattr(doc, "fields", {}) if doc else {}

    merchant = None
    tax = None
    total = None
    items = []

    if isinstance(fields, dict):
        merchant = (
            _field_content(fields.get("VendorName"))
            or _field_content(fields.get("MerchantName"))
            or _field_content(fields.get("Vendor"))
            or _field_content(fields.get("SupplierName"))
        )
        tax = _to_float(fields.get("TotalTax"))
        total = _to_float(fields.get("InvoiceTotal") or fields.get("Total"))
        items = _extract_items(fields.get("Items"))
    else:
        merchant = (
            _field_content(getattr(fields, "vendor_name", None))
            or _field_content(getattr(fields, "merchant_name", None))
            or _field_content(getattr(fields, "vendor", None))
            or _field_content(getattr(fields, "supplier_name", None))
        )
        tax = _to_float(getattr(fields, "total_tax", None))
        total = _to_float(getattr(fields, "invoice_total", None) or getattr(fields, "total", None))
        items = _extract_items(getattr(fields, "items", None))

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
    }
